{
  "decline_reason": "",
  "claims": [
    {
      "text": "Yes—under the Manual’s practice, relevant website statistics or other metrics may be used instead of sales figures where they more accurately demonstrate the trade mark’s capacity to distinguish.",
      "quotes": [
        {
          "ref": "TMM/Part23/4/4/1/1",
          "quote": "It is not always appropriate to insist on provision of turnover and/or marketing figures."
        },
        {
          "ref": "TMM/Part23/4/4/1/1",
          "quote": "Sometimes, the capacity to distinguish of a trade mark might be more accurately demonstrated by metrics other than revenue or promotional expenditure figures."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The relevance of alternative figures depends on the commercial realities of the claimed goods or services, rather than low turnover alone.",
      "quotes": [
        {
          "ref": "TMM/Part23/4/4/1/1",
          "quote": "Examiners must always consider the commercial realities relevant to the claimed goods and/or services when assessing evidence and maintaining grounds for rejection."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For website evidence, the Manual identifies Australian visitor figures since first use, broken down periodically if possible, together with references to websites where the trade mark is used.",
      "quotes": [
        {
          "ref": "TMM/Part23/3/3/4~2",
          "quote": "references to Internet website/s where trade mark is used, together with analytic figures which assist in determining the number of visitors to the website from Australia since the date of first use (if possible, broken down periodically)"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Other potentially relevant metrics include social media analytics, funds managed, raised or distributed, and video or podcast viewership.",
      "quotes": [
        {
          "ref": "TMM/Part23/4/4/1/1",
          "quote": "Other metrics that are relevant may include website and social media analytic figures, funds managed, raised, or distributed by an entity (e.g. in the case of a investment company or a charity), or viewership figures for videos, podcasts etc."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Small turnover may be compensated for by long use, especially where the trade mark has some inherent adaptation to distinguish.",
      "quotes": [
        {
          "ref": "TMM/Part23/4/4/1~1",
          "quote": "Massive turnover may compensate for short use, likewise, long use may compensate for small turnover, especially in relation to trade marks with some inherent adaptation to distinguish."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Any turnover figures provided should be assessed in the context of the relevant market and unit cost, with market-share information potentially supporting the evidence.",
      "quotes": [
        {
          "ref": "TMM/Part23/4/4/1~1",
          "quote": "However, total turnover must be considered in the context of the relevant market and balanced against unit cost before a decision can be made on this issue. Applicants should be encouraged to supply information on unit costs and perhaps market share to help support their case."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Alternative metrics are not an automatic substitute sufficient in every case: the Manual requires the strength of the evidence to be balanced against the trade mark’s level of inherent adaptation to distinguish.",
      "quotes": [
        {
          "ref": "TMM/Part23/4/4/1~2",
          "quote": "As a general comment, it is necessary to balance the level of inherent adaptation of the trade mark with the strength of the evidence provided."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0041",
    "GC-0058",
    "GC-0059",
    "GC-0009",
    "GC-0012",
    "GC-0081"
  ]
}
